def volcano_eruptions(x, y, n):
    count = 0
    remaining = n
    i = 1
    while remaining >= x:
        if i % 2 != 0:
            remaining -= x
        else:
            if remaining >= y:
                remaining -= y
            else:
                break
        count += 1
        i += 1
    return count

